// ToMarkdown renders the canonical subset back to deterministic Markdown.
// Assign references and attachments retain inert assign: identifiers and labels;
// no signed Assign download URL is included. Editable APIs additionally require
// the loss check in ToInterchangeMarkdown.
func ToMarkdown(raw []byte) ([]byte, error) {
	blocks, err := markdownTopLevelBlocks(raw)
	if err != nil {
		return nil, err
	}
	rendered := make([]string, len(blocks))
	for index, block := range blocks {
		rendered[index] = block.markdown
	}
	result := strings.Join(rendered, "\n\n")
	if result != "" {
		result += "\n"
	}
	return []byte(result), nil
}

